(function () {
  function palette(index) {
    return ["#39b980", "#2563eb", "#f59e0b", "#ef4444", "#7c3aed", "#0891b2"][index % 6];
  }

  class Chart {
    constructor(canvas, config) {
      this.canvas = canvas;
      this.ctx = canvas.getContext("2d");
      this.config = config;
      this.render();
    }

    destroy() {
      this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
    }

    render() {
      const rect = this.canvas.getBoundingClientRect();
      const dpr = window.devicePixelRatio || 1;
      this.canvas.width = Math.max(320, rect.width) * dpr;
      this.canvas.height = Math.max(220, rect.height || 260) * dpr;
      this.ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      this.ctx.clearRect(0, 0, rect.width, rect.height || 260);
      const type = this.config.type;
      if (type === "doughnut" || type === "pie") this.drawPie();
      if (type === "bar") this.drawBar();
      if (type === "line") this.drawLine();
    }

    drawPie() {
      const { labels, datasets } = this.config.data;
      const values = datasets[0].data.map(Number);
      const total = values.reduce((sum, value) => sum + value, 0) || 1;
      const cx = 112, cy = 112, radius = 76;
      let start = -Math.PI / 2;
      values.forEach((value, index) => {
        const angle = (value / total) * Math.PI * 2;
        this.ctx.beginPath();
        this.ctx.moveTo(cx, cy);
        this.ctx.arc(cx, cy, radius, start, start + angle);
        this.ctx.fillStyle = palette(index);
        this.ctx.fill();
        start += angle;
      });
      this.drawLegend(labels, values, 220, 64);
    }

    drawBar() {
      const { labels, datasets } = this.config.data;
      const values = datasets[0].data.map(Number);
      const max = Math.max(...values, 1);
      const width = this.canvas.clientWidth || 520;
      const height = this.canvas.clientHeight || 260;
      const barWidth = Math.max(18, (width - 80) / Math.max(values.length, 1) - 10);
      this.drawAxis(width, height);
      values.forEach((value, index) => {
        const x = 52 + index * (barWidth + 10);
        const h = ((height - 72) * value) / max;
        this.ctx.fillStyle = palette(index);
        this.ctx.fillRect(x, height - 42 - h, barWidth, h);
        this.drawLabel(labels[index], x, height - 18, barWidth + 16);
      });
    }

    drawLine() {
      const { labels, datasets } = this.config.data;
      const values = datasets[0].data.map(Number);
      const max = Math.max(...values, 1);
      const width = this.canvas.clientWidth || 520;
      const height = this.canvas.clientHeight || 260;
      this.drawAxis(width, height);
      this.ctx.beginPath();
      values.forEach((value, index) => {
        const x = 52 + (index * (width - 92)) / Math.max(values.length - 1, 1);
        const y = height - 42 - ((height - 72) * value) / max;
        if (index === 0) this.ctx.moveTo(x, y);
        else this.ctx.lineTo(x, y);
      });
      this.ctx.strokeStyle = "#2563eb";
      this.ctx.lineWidth = 3;
      this.ctx.stroke();
      values.forEach((value, index) => {
        const x = 52 + (index * (width - 92)) / Math.max(values.length - 1, 1);
        const y = height - 42 - ((height - 72) * value) / max;
        this.ctx.fillStyle = "#2563eb";
        this.ctx.beginPath();
        this.ctx.arc(x, y, 4, 0, Math.PI * 2);
        this.ctx.fill();
        if (index % Math.ceil(values.length / 5 || 1) === 0) this.drawLabel(labels[index], x - 20, height - 18, 50);
      });
    }

    drawAxis(width, height) {
      this.ctx.strokeStyle = "#d1d5db";
      this.ctx.lineWidth = 1;
      this.ctx.beginPath();
      this.ctx.moveTo(44, 18);
      this.ctx.lineTo(44, height - 38);
      this.ctx.lineTo(width - 20, height - 38);
      this.ctx.stroke();
    }

    drawLegend(labels, values, x, y) {
      labels.forEach((label, index) => {
        this.ctx.fillStyle = palette(index);
        this.ctx.fillRect(x, y + index * 28, 12, 12);
        this.ctx.fillStyle = getComputedStyle(document.documentElement).getPropertyValue("--text") || "#111827";
        this.ctx.font = "13px system-ui";
        this.ctx.fillText(`${label}: ${Math.round(values[index]).toLocaleString("fr-FR")}`, x + 20, y + 11 + index * 28);
      });
    }

    drawLabel(text, x, y, maxWidth) {
      this.ctx.fillStyle = getComputedStyle(document.documentElement).getPropertyValue("--muted") || "#6b7280";
      this.ctx.font = "11px system-ui";
      const label = String(text || "");
      const trimmed = label.length > 12 ? `${label.slice(0, 11)}...` : label;
      this.ctx.fillText(trimmed, x, y, maxWidth);
    }
  }

  window.Chart = Chart;
})();
